import React from 'react';
import { Link } from 'react-router-dom';
import '../styles/pages/Services.scss';
import siteData from '../data/siteData.json';

const Services = () => {
  const { servicesPage } = siteData;
  const { hero, services, cta } = servicesPage;

  return (
    <div className="services-page">
      <section className="services-hero">
        <div className="container">
          <h1>{hero.title}</h1>
          <p>{hero.subtitle}</p>
        </div>
      </section>

      <section className="services-list">
        <div className="container">
          <div className="services-grid">
            {services.map(service => (
              <div key={service.id} className="service-item">
                <div className="service-item__icon">{service.icon}</div>
                <h3>{service.title}</h3>
                <p>{service.description}</p>
                <div className="service-item__details">
                  <span className="price">{service.price}</span>
                  <span className="duration">{service.duration}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section className="services-cta">
        <div className="container">
          <h2>{cta.title}</h2>
          <p>{cta.description}</p>
          <Link to="/contact" className="btn btn-primary">{cta.button}</Link>
        </div>
      </section>
    </div>
  );
};

export default Services;
